69	    69	// Managed-plugin catalog (MASTER-PLAN 4.5): plugins Nxeon installs itself because Cyrus mods depend on them.
70	    70	// The entries are DATA (./catalog.json), validated here; one entry per (key, Minecraft family) so every family
71	    71	// has its own pinned version. Pure, except seedCatalog (DB upsert, server only).
72	    72	import catalogData from "./catalog.json";
73	    73	import { getVersion } from "../versions/registry";
74	    74	
75	    75	export type Family = "1.21" | "26";
76	    76	export type CatalogEntry = {
77	    77	  key: string;
78	    78	  displayName: string;
79	    79	  family: Family;
80	    80	  version: string;
81	    81	  pluginName: string;
82	    82	  source: "nxeon-built" | "hangar" | "modrinth" | "url";
83	    83	  sourceRef: string;
84	    84	  sha256: string;
85	    85	  artifact: string;
86	    86	  javaRelease: number;
87	    87	  /** SPDX id of the plugin's licence (optional, data only). */
88	    88	  licence?: string;
89	    89	  /** A ledger file next to catalog.json listing the runtime libraries the plugin downloads on first start. */
90	    90	  runtimeLibraries?: string;
91	    91	  /** A config file Nxeon writes for this plugin (template next to catalog.json, written to `path` on the server). */
92	    92	  managedConfig?: { path: string; template: string };
93	    93	};
