95	    95	const KEY_RE = /^[a-z][a-z0-9-]{1,47}$/;
96	    96	const SHA256_RE = /^[0-9a-f]{64}$/;
97	    97	const SOURCES = ["nxeon-built", "hangar", "modrinth", "url"] as const;
98	    98	
99	    99	export function validateCatalog(raw: unknown): { ok: true; entries: CatalogEntry[] } | { ok: false; errors: string[] } {
100	   100	  const errors: string[] = [];
101	   101	  const d = raw as { schema?: unknown; entries?: unknown };
102	   102	  if (!d || d.schema !== 1 || !Array.isArray(d.entries)) return { ok: false, errors: ["catalog must be { schema: 1, entries: [...] }"] };
103	   103	  const seen = new Set<string>();
104	   104	  const out: CatalogEntry[] = [];
105	   105	  for (const [i, e] of (d.entries as Record<string, unknown>[]).entries()) {
106	   106	    const at = `entries[${i}]`;
107	   107	    if (!KEY_RE.test(String(e.key ?? ""))) errors.push(`${at}.key must be lower-case kebab`);
108	   108	    if (e.family !== "1.21" && e.family !== "26") errors.push(`${at}.family must be "1.21" or "26"`);
109	   109	    if (!/^[0-9A-Za-z][0-9A-Za-z.+_-]{0,47}$/.test(String(e.version ?? ""))) errors.push(`${at}.version must be an exact version`);
110	   110	    if (!/^[A-Za-z0-9_-]{1,64}$/.test(String(e.pluginName ?? ""))) errors.push(`${at}.pluginName must be a plugin.yml name`);
111	   111	    if (!(SOURCES as readonly string[]).includes(String(e.source))) errors.push(`${at}.source must be one of ${SOURCES.join(", ")}`);
112	   112	    if (typeof e.sourceRef !== "string" || !e.sourceRef) errors.push(`${at}.sourceRef is required`);
113	   113	    if (!SHA256_RE.test(String(e.sha256 ?? ""))) errors.push(`${at}.sha256 must be a sha256 hex digest`);
114	   114	    if (typeof e.artifact !== "string" || !/^[A-Za-z0-9][A-Za-z0-9._/-]{0,199}$/.test(e.artifact) || e.artifact.split("/").includes("..")) errors.push(`${at}.artifact must be a relative path`);
115	   115	    if (!Number.isInteger(e.javaRelease) || (e.javaRelease as number) < 8 || (e.javaRelease as number) > 30) errors.push(`${at}.javaRelease must be a Java feature release`);
116	   116	    if (typeof e.displayName !== "string" || !e.displayName) errors.push(`${at}.displayName is required`);
117	   117	    const id = `${e.key}@${e.family}`;
118	   118	    if (seen.has(id)) errors.push(`${at}: duplicate ${id}`);
119	   119	    seen.add(id);
120	   120	    out.push(e as unknown as CatalogEntry);
121	   121	  }
122	   122	  return errors.length ? { ok: false, errors } : { ok: true, entries: out };
123	   123	}
