125	   125	/** The shipped catalog. Throws at load if the data file is invalid (a broken catalog must never half-work). */
126	   126	export function loadCatalog(): CatalogEntry[] {
127	   127	  const v = validateCatalog(catalogData);
128	   128	  if (!v.ok) throw new Error(`lib/cyrus/managed/catalog.json is invalid: ${v.errors.join("; ")}`);
129	   129	  return v.entries;
130	   130	}
