132	   132	export type PinResult = { ok: true; entry: CatalogEntry; family: Family } | { ok: false; code: "unknown_version" | "unknown_plugin" | "no_pin" | "java_too_old"; error: string };
133	   133	
134	   134	/** The pinned entry for a plugin on a server running `mcVersion` (exact registry id). Fails closed. */
135	   135	export function pinFor(entries: CatalogEntry[], key: string, mcVersion: string): PinResult {
136	   136	  const v = getVersion(mcVersion);
137	   137	  if (!v) return { ok: false, code: "unknown_version", error: `Minecraft ${mcVersion} is not in the version registry` };
138	   138	  const forKey = entries.filter((e) => e.key === key);
139	   139	  if (!forKey.length) return { ok: false, code: "unknown_plugin", error: `no managed plugin called ${key}` };
140	   140	  const entry = forKey.find((e) => e.family === v.family);
141	   141	  if (!entry) return { ok: false, code: "no_pin", error: `${key} has no pinned version for Minecraft ${v.family}.x` };
142	   142	  if (entry.javaRelease > v.javaRelease) return { ok: false, code: "java_too_old", error: `${key} ${entry.version} needs Java ${entry.javaRelease}; Minecraft ${mcVersion} servers run Java ${v.javaRelease}` };
143	   143	  return { ok: true, entry, family: v.family };
144	   144	}
