146	   146	type SeedDb = { cyrusManagedPlugin: { upsert: (a: any) => Promise<unknown> } }; // eslint-disable-line @typescript-eslint/no-explicit-any
147	   147	
148	   148	/** Upsert catalog rows from the data file (idempotent). Server only; run by an operator, not on request. */
149	   149	export async function seedCatalog(db: SeedDb, entries: CatalogEntry[] = loadCatalog()): Promise<number> {
150	   150	  for (const e of entries) {
151	   151	    const data = { displayName: e.displayName, version: e.version, pluginName: e.pluginName, source: e.source, sourceRef: e.sourceRef, sha256: e.sha256, artifact: e.artifact, javaRelease: e.javaRelease, active: true };
152	   152	    await db.cyrusManagedPlugin.upsert({ where: { key_family: { key: e.key, family: e.family } }, create: { key: e.key, family: e.family, ...data }, update: data });
153	   153	  }
154	   154	  return entries.length;
155	   155	}
156	   156	// How a managed plugin's jar gets onto (or off) a server. INJECTABLE: ensure/release (./service) only talk to this
157	   157	// interface, so the logic is tested with memoryInstaller(). The real one (engineManagedInstaller) places the jar
158	   158	// through the host's install engine (host.installs; Nxeon: lib/mods/engine.ts: guest state file, backup, staged write, rollback) and is
159	   159	// OFF unless CYRUS_MANAGED_PLUGINS_REAL=1. Called (flag-gated) by lib/cyrus/assets/deliver-worker.ts from the worker (docs "Cyrus asset slice (R1)").
160	   160	import { createHash } from "node:crypto";
161	   161	import { readFile } from "node:fs/promises";
162	   162	import path from "node:path";
163	   163	import type { CatalogEntry } from "./catalog";
164	   164	import { getHost, type HostGuestFs, type HostModFacts as CatalogFacts, type HostResolution as Resolution, type HostServerFacts as ServerFacts } from "../host";
165	   165	
166	   166	export type InstallReq = { serverId: string; entry: CatalogEntry; previousVersion: string | null };
167	   167	export type RemoveReq = { serverId: string; key: string; pluginName: string | null; version: string | null };
168	   168	export type InstallOutcome = { ok: true; version: string; sha256: string; notes?: string[] } | { ok: false; error: string };
169	   169	export type RemoveOutcome = { ok: true; notes?: string[] } | { ok: false; error: string };
170	   170	
171	   171	export interface ManagedInstaller {
172	   172	  install(req: InstallReq): Promise<InstallOutcome>;
173	   173	  remove(req: RemoveReq): Promise<RemoveOutcome>;
174	   174	}
175	   175	
176	   176	/** In-memory fake for tests and the sandbox: records what would be on each server. */
177	   177	export function memoryInstaller(opts: { fail?: (op: "install" | "remove", req: InstallReq | RemoveReq) => string | null } = {}) {
178	   178	  const servers = new Map<string, Map<string, { version: string; sha256: string }>>();
179	   179	  const calls: { op: "install" | "remove"; serverId: string; key: string; version: string | null }[] = [];
180	   180	  const inst: ManagedInstaller & { servers: typeof servers; calls: typeof calls } = {
181	   181	    servers,
182	   182	    calls,
183	   183	    async install(req) {
184	   184	      calls.push({ op: "install", serverId: req.serverId, key: req.entry.key, version: req.entry.version });
185	   185	      const err = opts.fail?.("install", req);
186	   186	      if (err) return { ok: false, error: err };
187	   187	      if (!servers.has(req.serverId)) servers.set(req.serverId, new Map());
188	   188	      servers.get(req.serverId)!.set(req.entry.key, { version: req.entry.version, sha256: req.entry.sha256 });
189	   189	      return { ok: true, version: req.entry.version, sha256: req.entry.sha256 };
190	   190	    },
191	   191	    async remove(req) {
192	   192	      calls.push({ op: "remove", serverId: req.serverId, key: req.key, version: req.version });
193	   193	      const err = opts.fail?.("remove", req);
194	   194	      if (err) return { ok: false, error: err };
195	   195	      servers.get(req.serverId)?.delete(req.key);
196	   196	      return { ok: true };
197	   197	    },
198	   198	  };
199	   199	  return inst;
200	   200	}
