206	   206	/** Read a catalog artifact from CYRUS_MANAGED_PLUGIN_DIR and verify its sha256 against the pin. */
207	   207	export async function readManagedArtifact(entry: CatalogEntry, dir = process.env.CYRUS_MANAGED_PLUGIN_DIR || ""): Promise<Buffer> {
208	   208	  if (!dir || !path.isAbsolute(dir)) throw new Error("CYRUS_MANAGED_PLUGIN_DIR must be an absolute path");
209	   209	  const p = path.join(dir, entry.artifact);
210	   210	  if (!p.startsWith(path.resolve(dir) + path.sep)) throw new Error("artifact path escapes the managed plugin dir");
211	   211	  const bytes = await readFile(p);
212	   212	  const sha = createHash("sha256").update(bytes).digest("hex");
213	   213	  if (sha !== entry.sha256) throw new Error(`${entry.key} ${entry.version}: artifact sha256 ${sha} does not match the pin ${entry.sha256}`);
