276	   276	export const DEPENDENT_RE = /^(project|mod):[A-Za-z0-9_-]{1,64}$/;
277	   277	export type ManagedStatus = "installing" | "installed" | "failed" | "removing" | "removed";
278	   278	export type ManagedRow = { status: ManagedStatus; version: string | null; sha256: string | null; family: string; dependents: string[] };
279	   279	
280	   280	export type EnsurePlan =
281	   281	  | { kind: "install" | "upgrade"; dependents: string[] }
282	   282	  | { kind: "addRef" | "noop"; dependents: string[] }
283	   283	  | { kind: "busy"; dependents: string[] };
284	   284	export type ReleasePlan = { kind: "remove" | "decRef" | "noop" | "busy"; dependents: string[] };
285	   285	
286	   286	const withDep = (deps: string[], d: string) => [...new Set([...deps, d])].sort();
287	   287	
288	   288	export function planEnsure(row: ManagedRow | null, dependent: string, pin: CatalogEntry): EnsurePlan {
289	   289	  if (!DEPENDENT_RE.test(dependent)) throw new Error(`bad dependent id ${dependent}`);
290	   290	  const current = row?.dependents ?? [];
291	   291	  if (row && (row.status === "installing" || row.status === "removing")) return { kind: "busy", dependents: current };
292	   292	  const deps = withDep(row && row.status !== "removed" ? current : [], dependent);
293	   293	  if (!row || row.status === "removed" || row.status === "failed" || !row.version) return { kind: "install", dependents: deps };
294	   294	  if (row.version !== pin.version || row.sha256 !== pin.sha256 || row.family !== pin.family) return { kind: "upgrade", dependents: deps };
295	   295	  return current.includes(dependent) ? { kind: "noop", dependents: current } : { kind: "addRef", dependents: deps };
296	   296	}
297	   297	
298	   298	export function planRelease(row: ManagedRow | null, dependent: string): ReleasePlan {
299	   299	  if (!DEPENDENT_RE.test(dependent)) throw new Error(`bad dependent id ${dependent}`);
300	   300	  if (!row || row.status === "removed") return { kind: "noop", dependents: [] };
301	   301	  if (row.status === "installing" || row.status === "removing") return { kind: "busy", dependents: row.dependents };
302	   302	  // A failed removal left nothing depending on it: releasing again retries the removal.
303	   303	  if (row.status === "failed" && row.dependents.length === 0) return { kind: "remove", dependents: [] };
304	   304	  if (!row.dependents.includes(dependent)) return { kind: "noop", dependents: row.dependents };
305	   305	  const rest = row.dependents.filter((d) => d !== dependent);
306	   306	  return rest.length ? { kind: "decRef", dependents: rest } : { kind: "remove", dependents: [] };
307	   307	}
