324	   324	type Db = Pick<PrismaClient, "$transaction" | "cyrusServerManagedPlugin">;
325	   325	type Tx = Prisma.TransactionClient;
326	   326	export type ManagedDeps = { db: Db; installer: ManagedInstaller; catalog: CatalogEntry[] };
327	   327	
328	   328	export type EnsureResult =
329	   329	  | { ok: true; action: "installed" | "upgraded" | "ref_added" | "already"; version: string; refCount: number }
330	   330	  | { ok: false; code: "bad_input" | "unknown_version" | "unknown_plugin" | "no_pin" | "java_too_old" | "busy" | "install_failed"; error: string };
331	   331	export type ReleaseResult =
332	   332	  | { ok: true; action: "removed" | "ref_dropped" | "not_held"; refCount: number }
333	   333	  | { ok: false; code: "bad_input" | "busy" | "remove_failed"; error: string };
