335	   335	type RowRec = { id: string; status: string; version: string | null; sha256: string | null; family: string; dependents: unknown; refCount: number };
336	   336	const toRow = (r: RowRec): ManagedRow => ({
337	   337	  status: r.status as ManagedStatus, version: r.version, sha256: r.sha256, family: r.family,
338	   338	  dependents: Array.isArray(r.dependents) ? (r.dependents as unknown[]).filter((d): d is string => typeof d === "string").sort() : [],
339	   339	});
