341	   341	/** Get-or-create the row and lock it for this transaction. A fresh row starts as `removed` with no dependents. */
342	   342	async function lockRow(tx: Tx, serverId: string, key: string, family: string): Promise<RowRec> {
343	   343	  // INSERT .. ON CONFLICT DO NOTHING: racing first calls never raise (a unique violation would abort the transaction).
344	   344	  await tx.$executeRaw`INSERT INTO "CyrusServerManagedPlugin" ("id","serverId","key","family","status","dependents","refCount","createdAt","updatedAt")
345	   345	    VALUES (${"csmp_" + randomUUID().replace(/-/g, "")}, ${serverId}, ${key}, ${family}, 'removed', '[]'::jsonb, 0, now(), now())
346	   346	    ON CONFLICT ("serverId","key") DO NOTHING`;
347	   347	  const rows = await tx.$queryRaw<RowRec[]>`SELECT "id","status","version","sha256","family","dependents","refCount" FROM "CyrusServerManagedPlugin" WHERE "serverId" = ${serverId} AND "key" = ${key} FOR UPDATE`;
348	   348	  if (!rows[0]) throw new Error("managed plugin row vanished");
349	   349	  return rows[0];
350	   350	}
