352	   352	export async function ensureManagedPlugin(deps: ManagedDeps, args: { serverId: string; key: string; mcVersion: string; dependent: string }): Promise<EnsureResult> {
353	   353	  if (!args.serverId || !DEPENDENT_RE.test(args.dependent)) return { ok: false, code: "bad_input", error: "serverId and a dependent id (project:<id> or mod:<id>) are required" };
354	   354	  const pin = pinFor(deps.catalog, args.key, args.mcVersion);
355	   355	  if (!pin.ok) return { ok: false, code: pin.code, error: pin.error };
356	   356	  const entry = pin.entry;
357	   357	
358	   358	  const step1 = await deps.db.$transaction(async (tx) => {
359	   359	    const rec = await lockRow(tx, args.serverId, args.key, entry.family);
360	   360	    const row = toRow(rec);
361	   361	    const plan = planEnsure(rec.status === "removed" && !row.dependents.length && !rec.version ? null : row, args.dependent, entry);
362	   362	    if (plan.kind === "busy") return { plan, rec, prev: row };
363	   363	    const data: Prisma.CyrusServerManagedPluginUpdateInput = { dependents: plan.dependents, refCount: plan.dependents.length };
364	   364	    if (plan.kind === "install" || plan.kind === "upgrade") Object.assign(data, { status: "installing", family: entry.family, error: null });
365	   365	    await tx.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data });
366	   366	    return { plan, rec, prev: row };
367	   367	  });
368	   368	  const { plan, rec, prev } = step1;
369	   369	  if (plan.kind === "busy") return { ok: false, code: "busy", error: `${entry.displayName} is being changed on this server right now; try again shortly` };
370	   370	  if (plan.kind === "noop" || plan.kind === "addRef") return { ok: true, action: plan.kind === "noop" ? "already" : "ref_added", version: prev.version ?? entry.version, refCount: plan.dependents.length };
371	   371	
372	   372	  let out: Awaited<ReturnType<ManagedInstaller["install"]>>;
373	   373	  try {
374	   374	    out = await deps.installer.install({ serverId: args.serverId, entry, previousVersion: prev.status === "installed" || prev.status === "failed" ? prev.version : null });
375	   375	  } catch (e) {
376	   376	    out = { ok: false, error: (e as Error).message || "installer threw" };
377	   377	  }
378	   378	  if (out.ok) {
379	   379	    await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "installed", version: out.version, sha256: out.sha256, installedAt: new Date(), error: null } });
380	   380	    return { ok: true, action: plan.kind === "upgrade" ? "upgraded" : "installed", version: out.version, refCount: plan.dependents.length };
381	   381	  }
382	   382	  // The dependent stays recorded (desired state): the next ensure retries the install.
383	   383	  await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "failed", error: out.error.slice(0, 500) } });
384	   384	  return { ok: false, code: "install_failed", error: out.error };
385	   385	}
