387	   387	export async function releaseManagedPlugin(deps: ManagedDeps, args: { serverId: string; key: string; dependent: string }): Promise<ReleaseResult> {
388	   388	  if (!args.serverId || !DEPENDENT_RE.test(args.dependent)) return { ok: false, code: "bad_input", error: "serverId and a dependent id are required" };
389	   389	  const existing = await deps.db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: args.serverId, key: args.key } } });
390	   390	  if (!existing) return { ok: true, action: "not_held", refCount: 0 };
391	   391	  const pluginName = deps.catalog.find((e) => e.key === args.key)?.pluginName ?? null;
392	   392	
393	   393	  const step1 = await deps.db.$transaction(async (tx) => {
394	   394	    const rec = await lockRow(tx, args.serverId, args.key, existing.family);
395	   395	    const plan = planRelease(toRow(rec), args.dependent);
396	   396	    if (plan.kind === "busy" || plan.kind === "noop") return { plan, rec };
397	   397	    const data: Prisma.CyrusServerManagedPluginUpdateInput = { dependents: plan.dependents, refCount: plan.dependents.length };
398	   398	    if (plan.kind === "remove") Object.assign(data, { status: "removing", error: null });
399	   399	    await tx.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data });
400	   400	    return { plan, rec };
401	   401	  });
402	   402	  const { plan, rec } = step1;
403	   403	  if (plan.kind === "busy") return { ok: false, code: "busy", error: "this managed plugin is being changed right now; try again shortly" };
404	   404	  if (plan.kind === "noop") return { ok: true, action: "not_held", refCount: plan.dependents.length };
405	   405	  if (plan.kind === "decRef") return { ok: true, action: "ref_dropped", refCount: plan.dependents.length };
406	   406	
407	   407	  let out: Awaited<ReturnType<ManagedInstaller["remove"]>>;
408	   408	  try {
409	   409	    out = await deps.installer.remove({ serverId: args.serverId, key: args.key, pluginName, version: rec.version });
410	   410	  } catch (e) {
411	   411	    out = { ok: false, error: (e as Error).message || "installer threw" };
412	   412	  }
413	   413	  if (out.ok) {
414	   414	    await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "removed", version: null, sha256: null, installedAt: null, error: null } });
415	   415	    return { ok: true, action: "removed", refCount: 0 };
416	   416	  }
417	   417	  await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "failed", error: out.error.slice(0, 500) } });
418	   418	  return { ok: false, code: "remove_failed", error: out.error };
419	   419	}
