434	   434	/** Put every row back to the snapshot (rows created since are removed). Runs in one transaction, rows locked. */
435	   435	export async function restoreServerManaged(db: Pick<PrismaClient, "$transaction">, snap: ManagedSnapshot): Promise<void> {
436	   436	  await db.$transaction(async (tx) => {
437	   437	    const now = await tx.$queryRaw<{ key: string }[]>`SELECT "key" FROM "CyrusServerManagedPlugin" WHERE "serverId" = ${snap.serverId} FOR UPDATE`;
