 47	/** Re-compile stored creatures and prove the bytes equal what the build recorded (shared with lib/cyrus/delivery). */
 48	export function compileStoredCreatures(namespace: string, creatures: StoredCreature[]): { ok: true; files: { rel: string; data: Buffer }[] } | { ok: false; error: string } {
 49	  const files: { rel: string; data: Buffer }[] = [];
 50	  for (const c of creatures) {
 51	    const chk = checkRigSpec(c.spec, { namespace });
 52	    if (!chk.ok) return { ok: false, error: `creature ${c.name}: ${chk.error}` };
 53	    let paint: ((b: import("../textures/render").Raster) => import("../textures/render").Raster) | undefined;
 54	    if (c.paint !== undefined) {
 55	      const size = (c.paint as { tex?: { w?: number } } | null)?.tex?.w ?? 0;
 56	      const pc = checkCreaturePaint(c.paint, size);
 57	      if (!pc.ok) return { ok: false, error: `creature ${c.name}: ${pc.reason}` };
 58	      paint = paintSkin(c.paint as CreaturePaint);
 59	    }
 60	    const r = compileCreature(chk.spec, namespace, { paint });
 61	    if (!r.ok) return { ok: false, error: `creature ${c.name}: ${r.error}` };
 62	    if (r.creature.bbmodelSha256 !== c.bbmodelSha256 || r.creature.key !== modelKey(namespace, chk.spec.name)) return { ok: false, error: `creature ${c.name}: the model no longer compiles to the recorded bytes (compiler changed?); rebuild the mod` };
 63	    files.push({ rel: `${MODELS_DIR}/${r.creature.key}.bbmodel`, data: Buffer.from(r.creature.bbmodel) });
 64	  }
 65	  return { ok: true, files };
 66	}
