 68	export async function deliverCreatures(a: { serverId: string; mcVersion: string; namespace: string; projectId: string; creatures: StoredCreature[] }, deps: CreatureDeliverDeps): Promise<CreatureDeliverResult> {
 69	  const env = deps.env ?? process.env;
 70	  if (!creaturesSwitchedOn(env)) return { ok: true, action: "switched_off", wrote: [], removed: [], restartRequired: false, notes: [`animated creature delivery is switched off (${MANAGED_REAL_FLAG} and ${CREATURES_FLAG} must both be 1)`] };
 71	  const base = deps.base ?? MC_BASE;
 72	  // compile first: nothing touches the server unless every model re-compiles to the recorded bytes
 73	  const compiled = compileStoredCreatures(a.namespace, a.creatures);
 74	  if (!compiled.ok) return compiled;
 75	  const files = compiled.files;
 76	  const notes: string[] = [];
 77	  let bettermodel: string | undefined;
 78	  let restartRequired = false;
 79	  if (files.length) {
 80	    const ens = await ensureManagedPlugin(deps.managed, { serverId: a.serverId, key: BETTERMODEL_KEY, mcVersion: a.mcVersion, dependent: dependentFor(a.projectId) });
 81	    if (!ens.ok) return { ok: false, error: `BetterModel: ${ens.error}` };
 82	    bettermodel = ens.action;
 83	    if (ens.action === "installed" || ens.action === "upgraded") { restartRequired = true; notes.push("the Nxeon-managed BetterModel plugin was installed; it starts with the next server restart"); }
 84	  }
 85	  const wrote: string[] = [];
 86	  // managed config: only when absent or still ours (an owner who edited it keeps their file)
 87	  const cfgPath = `${base}/${CONFIG_PATH}`;
 88	  if (files.length) {
 89	    const cur = await deps.fs.readFile(cfgPath, 256 * 1024);
 90	    const want = Buffer.from(deps.configTemplate ? deps.configTemplate() : managedConfigTemplate(a.mcVersion));
 91	    if (!cur || (cur.toString("utf8").startsWith(CONFIG_MARKER) && !cur.equals(want))) {
 92	      await deps.fs.mkdirp(path.posix.dirname(cfgPath));
 93	      await deps.fs.writeFile(cfgPath, want);
 94	      wrote.push(CONFIG_PATH); restartRequired = true;
 95	    } else if (!cur.toString("utf8").startsWith(CONFIG_MARKER)) notes.push("BetterModel's config.yml was changed by the server owner, so Nxeon left it as it is");
 96	  }
 97	  await deps.fs.mkdirp(`${base}/${MODELS_DIR}`);
 98	  for (const f of files) {
 99	    const cur = await deps.fs.readFile(`${base}/${f.rel}`, 4 * 1024 * 1024);
100	    if (cur && cur.equals(f.data)) continue;
101	    const tmp = `${base}/${f.rel}.nx-part`;
102	    await deps.fs.writeFile(tmp, f.data);
103	    await deps.fs.rename(tmp, `${base}/${f.rel}`);
104	    wrote.push(f.rel); restartRequired = true;
105	  }
106	  // this project's models the new version no longer has (only files with OUR namespace prefix; others untouched)
107	  const keep = new Set(files.map((f) => path.posix.basename(f.rel)));
108	  const removed: string[] = [];
109	  for (const name of await deps.fs.list(`${base}/${MODELS_DIR}`).catch(() => [] as string[])) {
110	    if (!name.startsWith(`${a.namespace}_`) || !name.endsWith(".bbmodel") || keep.has(name)) continue;
111	    await deps.fs.remove(`${base}/${MODELS_DIR}/${name}`);
112	    removed.push(`${MODELS_DIR}/${name}`); restartRequired = true;
113	  }
114	  if (!files.length) {
115	    const rel = await releaseManagedPlugin(deps.managed, { serverId: a.serverId, key: BETTERMODEL_KEY, dependent: dependentFor(a.projectId) });
116	    if (!rel.ok) return { ok: false, error: `BetterModel: ${rel.error}` };
117	    return { ok: true, action: removed.length ? "removed" : "no_creatures", wrote, removed, restartRequired, bettermodel: rel.action, notes };
118	  }
119	  if (restartRequired) notes.push("restart the server (or run /bettermodel reload) so BetterModel loads the creatures and rebuilds its resource pack");
120	  return { ok: true, action: "delivered", wrote, removed, restartRequired, bettermodel, notes };
121	}
