 27	export async function deliverBuildPack(serverId: string, build: DeliverBuild, deps: DeliverDeps): Promise<DeliverResult> {
 28	  const a = readBuildAssets(build.result);
 29	  if (!a?.loader || a.status !== "ready") return { ok: true, action: "no_pack", wrote: false, notes: [] };
 30	  if ((deps.env ?? process.env)[PACK_DELIVERY_FLAG] !== "1") {
 31	    return { ok: true, action: "switched_off", wrote: false, notes: [`custom-texture pack delivery is switched off (${PACK_DELIVERY_FLAG} is not 1); the plugin was installed without it`] };
 32	  }
