 35	  if (!ens.ok) return { ok: false, error: `Nxeon Pack Loader: ${ens.error}` };
 36	  const cur = await readLoaderConfig(deps.fs, deps.base);
 37	  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
