 42	  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config, deps.base) : false;
 43	  const notes = [...r.warnings.map((w) => w.message)];
 44	  if (ens.action === "installed" || ens.action === "upgraded") notes.push("the Nxeon Pack Loader was installed; it starts with the next server restart");
