 59	  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
 60	  const r = applyPackChange(cur.config, { op: "remove", namespace: ident.namespace, role: PACK_ROLE }, { urlFor: () => "" });
 61	  if (!r.ok) return { ok: false, error: r.error };
 62	  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config, deps.base) : false;
 63	  const rel = await releaseManagedPlugin(deps.managed, { serverId, key: PACK_LOADER_KEY, dependent: dependentFor(ident.projectId) });
