327	async function deliverBody(t: Txn, r: ModRelease, prev: DeliveryRecord | null, p: { datapacks: ModRelease["datapacks"]; pack: ModRelease["pack"]; models: { rel: string; data: Buffer }[]; notes: string[]; packOwners: string[]; plugins: string[]; serverProperties: Record<string, string> }): Promise<BodyOut> {
328	  const { session, jfs, host } = t;
329	  const base = session.base, level = session.levelName;
330	  const mc = session.mcVersion ?? r.mcVersion;
331	  t.notes.push(...p.notes);
332	  const dep = dependentFor(r.projectId);
333	  const managedNow = new Set<string>();
334	  let managedChanged = false;
335	  const expectPlugins: string[] = [];
336	  // 1. managed plugins
337	  const wantLoader = !!p.pack, wantBm = p.models.length > 0;
338	  await timed(t, "managed", async () => {
339	    const out: string[] = [];
340	    for (const [key, want] of [[PACK_LOADER_KEY, wantLoader], [BETTERMODEL_KEY, wantBm]] as const) {
341	      const had = prev?.managed.includes(key) ?? false;
342	      if (want) {
343	        t.refsTouched = true;
344	        const e = await host.managed.ensure({ serverId: t.serverId, key, mcVersion: mc, dependent: dep, fs: jfs });
345	        if (!e.ok) throw new Error(`${key}: ${e.error}`);
346	        managedNow.add(key); expectPlugins.push(e.pluginName);
347	        if (e.action === "installed" || e.action === "upgraded") managedChanged = true;
348	        out.push(`${key} ${e.action}`);
349	      } else if (had) {
350	        t.refsTouched = true;
351	        const rel = await host.managed.release({ serverId: t.serverId, key, dependent: dep, fs: jfs });
352	        if (!rel.ok) throw new Error(`${key}: ${rel.error}`);
353	        if (rel.action === "removed") managedChanged = true;
354	        out.push(`${key} ${rel.action}`);
355	      }
356	    }
357	    return out.join(", ") || "none needed";
358	  }, (v) => v);
359	  // 2. pack hosting
360	  let packUrl: string | null = null;
361	  if (p.pack) {
362	    packUrl = await timed(t, "host_pack", async () => {
363	      if (p.pack!.zip && host.packs) return (await host.packs.publish(p.pack!.zip, p.pack!.sha1)).url;
364	      if (p.pack!.url) return p.pack!.url;
365	      throw new Error("no pack hosting configured");
366	    }, (u) => `hosted at ${u}`);
367	    if (!/^https:\/\//.test(packUrl)) throw new StepFail("host_pack", "the pack URL must be https");
368	  } else skip(t, "host_pack", "no resource pack in this delivery");
369	  // 3. Pack Loader config
370	  let loaderChanged = false;
371	  const loaderIds: string[] = [];
372	  if (p.pack || prev?.packLoaderIds.length) {
373	    await timed(t, "pack_config", async () => {
374	      const cur = await readLoaderConfig(jfs as unknown as GuestFs, base);
375	      if (!cur.ok) throw new Error(cur.error);
376	      const existed = cur.config?.packs.map((x) => `${x.owner ?? "?"}:${x.id.slice(0, 8)}`) ?? [];
377	      const ch = p.pack
378	        ? applyPackChange(cur.config, { op: "upsert", namespace: r.namespace, role: PACK_ROLE, sha1: p.pack.sha1, prompt: p.pack.prompt, required: p.pack.required, owner: `project:${r.projectId}` }, { urlFor: (s) => { if (s !== p.pack!.sha1) throw new Error("pack url for another sha1"); return packUrl!; } }, { plugins: p.plugins, serverProperties: p.serverProperties })
379	        : applyPackChange(cur.config, { op: "remove", namespace: r.namespace, role: PACK_ROLE }, { urlFor: () => "" });
380	      if (!ch.ok) throw new Error(ch.error);
381	      for (const w of ch.warnings) t.notes.push(w.message);
382	      if (p.packOwners.length) t.notes.push(`this server already has another resource-pack owner (${p.packOwners.join(", ")}); players may get two pack prompts`);
383	      if (p.pack) loaderIds.push(ch.id);
384	      if (ch.changed) { await writeLoaderConfig(jfs as unknown as GuestFs, ch.config, base); loaderChanged = true; }
385	      return `${ch.action}${existed.length ? `; other entries kept: ${existed.length}` : ""}`;
386	    }, (v) => v);
387	  } else skip(t, "pack_config", "no pack entry to change");
388	  // 4. place: jar, data packs, creature models
389	  let jarChanged = false, modelsChanged = false, managedConfigChanged = false;
390	  const placedDps: DeliveryRecord["datapacks"] = [];
391	  const models: DeliveryRecord["models"] = [];
392	  let jar: DeliveryRecord["jar"] = null;
393	  const dpApply: ApplyInput["datapacks"] = [];
394	  await timed(t, "place", async () => {
395	    if (r.plugin) {
396	      const cur = prev?.jar ? await jfs.readFile(prev.jar.target) : null;
397	      const same = !!prev?.jar && cur !== null && sha256(cur) === r.plugin.sha256 && prev.jar.target.endsWith(`/${r.plugin.jarName}`);
398	      if (!same) {
399	        const j = await host.jar.install({ serverId: t.serverId, fs: jfs, base, release: r, previous: prev });
400	        if (!j.ok) throw new Error(`plugin jar: ${j.error}`);
401	        const placed = await jfs.readFile(j.target);
402	        if (!placed || sha256(placed) !== r.plugin.sha256) throw new Error("the plugin jar on the server does not verify after placing it");
403	        jar = { target: j.target, sha256: r.plugin.sha256 };
404	        jarChanged = true;
405	      } else jar = prev!.jar;
406	      expectPlugins.push(r.plugin.pluginName);
407	    } else if (prev?.jar) {
408	      const rm = await host.jar.remove({ serverId: t.serverId, fs: jfs, base, record: prev });
409	      if (!rm.ok) throw new Error(`removing the previous plugin jar: ${rm.error}`);
410	      jarChanged = true;
411	    }
412	    for (const d of p.datapacks) {
413	      const target = `${base}/${level}/datapacks/${datapackFile(r.namespace, d.name)}`;
414	      const cur = await jfs.readFile(target);
415	      const changed = !cur || sha256(cur) !== d.sha256;
416	      if (changed) { await jfs.mkdirp(`${base}/${level}/datapacks`); await jfs.writeFile(`${target}.nxeon-part`, d.zip); await jfs.rename(`${target}.nxeon-part`, target); }
417	      placedDps.push({ name: d.name, target, sha256: d.sha256, apply: d.apply, ...(d.worldgen ? { dimensions: d.worldgen.dimensions } : {}) });
418	      dpApply.push({ changed, apply: d.apply, worldgen: !!d.worldgen });
419	    }
420	    for (const old of prev?.datapacks ?? []) {
421	      if (placedDps.some((x) => x.target === old.target)) continue;
422	      if (await jfs.stat(old.target)) await jfs.remove(old.target);
423	      dpApply.push({ changed: true, apply: old.apply, worldgen: !!old.dimensions?.length });
424	    }
425	    if (p.models.length) {
426	      const cfg = `${base}/${BM_CONFIG_PATH}`;
427	      const cur = await jfs.readFile(cfg, 256 * 1024);
428	      const want = Buffer.from((host.betterModelConfig ?? managedConfigTemplate)());
