459	/** Remove a delivered mod: jar, data packs, models, pack entry; release managed plugins (ref-counted). Dimension
460	 *  world folders are KEPT (players' builds live there) and listed in `keptWorldFolders` for an admin cleanup action. */
461	export async function uninstallMod(serverId: string, projectId: string, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
462	  return transaction({
463	    serverId, op: "uninstall", subject: { projectId }, host, label: `uninstall-${projectId}`, opts,
464	    prepare: async (session, steps) => timed({ steps, host }, "preflight", async () => {
465	      const prev = readRecord(await session.fs.readFile(recordPath(projectId), 1024 * 1024));
466	      if (!prev) return { body: async (t: Txn) => { await t.jfs.commit(); return { apply: { jarChanged: false, managedChanged: false, datapacks: [], modelsChanged: false, managedConfigChanged: false, loaderChanged: false }, expect: { plugins: [], datapacks: [], worldgen: false }, record: null, outcome: "unchanged" as const, unchanged: true }; } };
467	      if (prev.packLoaderIds.length) {
468	        const cur = await readLoaderConfig(session.fs as unknown as GuestFs, session.base);
469	        if (!cur.ok) throw new Refusal("preflight", `the server's pack config is invalid, so nothing was changed: ${cur.error}`);
470	      }
471	      return { body: (t: Txn) => uninstallBody(t, prev) };
472	    }, () => "delivery record found"),
473	  });
474	}
