476	async function uninstallBody(t: Txn, prev: DeliveryRecord): Promise<BodyOut> {
477	  const { jfs, session, host } = t;
478	  const base = session.base;
479	  let managedChanged = false, loaderChanged = false, jarChanged = false, modelsChanged = false;
480	  const dp: ApplyInput["datapacks"] = [];
481	  await timed(t, "pack_config", async () => {
482	    if (!prev.packLoaderIds.length) return "no pack entry";
483	    const cur = await readLoaderConfig(jfs as unknown as GuestFs, base);
484	    if (!cur.ok) throw new Error(cur.error);
485	    const ch = applyPackChange(cur.config, { op: "remove", namespace: prev.namespace, role: PACK_ROLE }, { urlFor: () => "" });
486	    if (!ch.ok) throw new Error(ch.error);
487	    if (ch.changed) { await writeLoaderConfig(jfs as unknown as GuestFs, ch.config, base); loaderChanged = true; }
488	    return ch.action;
489	  }, (v) => v);
490	  await timed(t, "place", async () => {
491	    if (prev.jar) { const rm = await host.jar.remove({ serverId: t.serverId, fs: jfs, base, record: prev }); if (!rm.ok) throw new Error(rm.error); jarChanged = true; }
492	    for (const d of prev.datapacks) { if (await jfs.stat(d.target)) await jfs.remove(d.target); dp.push({ changed: true, apply: d.apply, worldgen: !!d.dimensions?.length }); }
493	    for (const m of prev.models) if (await jfs.stat(m.target)) { await jfs.remove(m.target); modelsChanged = true; }
494	    return `removed jar ${prev.jar ? "yes" : "none"}, ${prev.datapacks.length} data pack(s), ${prev.models.length} model(s)`;
495	  }, (v) => v);
496	  await timed(t, "managed", async () => {
497	    const out: string[] = [];
498	    for (const key of prev.managed) {
499	      t.refsTouched = true;
500	      const rel = await host.managed.release({ serverId: t.serverId, key, dependent: dependentFor(prev.projectId), fs: jfs });
501	      if (!rel.ok) throw new Error(`${key}: ${rel.error}`);
502	      if (rel.action === "removed") managedChanged = true;
503	      out.push(`${key} ${rel.action}`);
504	    }
505	    return out.join(", ") || "none held";
506	  }, (v) => v);
507	  await timed(t, "record", async () => { await jfs.remove(recordPath(prev.projectId)); return "record removed"; }, (v) => v);
508	  const kept: string[] = [];
509	  for (const f of dimensionFolders(base, session.levelName, prev.datapacks.flatMap((d) => d.dimensions ?? []))) if ((await jfs.stat(f))?.type === "dir") kept.push(f);
510	  if (kept.length) t.notes.push(`The dimension world folder(s) ${kept.join(", ")} were kept (players' builds live there); an admin can delete them.`);
511	  return {
512	    apply: { jarChanged, managedChanged, datapacks: dp, modelsChanged, managedConfigChanged: false, loaderChanged }, record: null, outcome: "uninstalled", keptWorldFolders: kept,
513	    expect: { plugins: [], pluginsGone: prev.pluginName && prev.jar ? [prev.pluginName] : [], datapacks: [], worldgen: dp.some((d) => d.worldgen) },
514	  };
515	}
