1	/**
2	 * Cyrus R5 delivery job (worker side): Nxeon's implementation of the orchestrator's host seam
3	 * (lib/cyrus/delivery/types.ts DeliveryHost) and the job entry point.
4	 *
5	 * Wiring (the only one, and only as far as is clearly safe): a GAME_MOD_SYNC job whose payload carries
6	 * `{ cyrusDelivery: { v: 1, op, buildId?, projectId?, serverModId?, prev?, restartPolicy, key, acknowledge?, ... } }`
7	 * (schema: lib/cyrus/delivery/request.ts; op "config" = a Config Studio values-only send, handled by deliverConfig)
8	 * (a payload DISCRIMINATOR on an existing job type: no new enum value, no new table) is handed to
9	 * `cyrusDeliveryJob` instead of the normal mod reconcile. The portal enqueues it through lib/modbuilder/delivery.ts
10	 * (route app/api/cyrus/delivery/v1, wiring phase 2); the job body itself is host-neutral (lib/cyrus/delivery/job.ts) and
11	 * refuses unless CYRUS_DELIVERY=1 in the worker. Each part is still behind its own flag (CYRUS_MANAGED_PLUGINS_REAL,
12	 * CYRUS_DATAPACK_DELIVERY_REAL (+ CYRUS_WORLDGEN), CYRUS_CREATURES) and the Mods engine's ENABLE_REAL_GAMEMODS.
13	 * The GAME_MOD_SYNC job already holds the per-server lock (one job per server at a time).
14	 *
15	 * The result (steps, rollback, health, notes) is stored on the job's payload.result.cyrusDelivery: the admin read
16	 * model (lib/cyrus/delivery/admin.ts) lists recent deliveries from there.
17	 *
18	 * SANDBOX: the server is the fake guest dir; a "restart" cannot boot anything there, so the health probe reports
19	 * `real: false` and a delivery that needs a restart is honestly rolled back (use restartPolicy "next_restart" there).
20	 */
21	import type { Job, Prisma } from "@prisma/client";
22	import { readFile } from "node:fs/promises";
23	import { db } from "../lib/db";
24	import { cyrusDb } from "../lib/cyrus/db";
