55	type ServerRow = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
56	const loadServer = (id: string) => db.server.findUnique({ where: { id }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
57	const MC = cyrusConfig().guest.mcBase;
58	const LOG = `${MC}/logs/latest.log`;
59	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
