61	/** Health facts from a Paper latest.log (pure; moved to lib/cyrus/delivery/bootlog.ts, re-exported here unchanged). */
62	export { parseBootLog };
63	
64	function session(server: ServerRow, fs: GuestFs, levelName: string): ServerSession {
65	  const spec = controlSpec("minecraft");
66	  const readLog = async () => (await fs.readFile(LOG, 8 * 1024 * 1024))?.toString("utf8") ?? "";
67	  let preLog: string | null = null;
68	  const rcon = async (cmd: string) => {
69	    if (SANDBOX || !spec) return { ok: false as const, error: "no console here" };
70	    try { const r = await withServerSsh(server, (conn) => runRcon(conn, spec, cmd)); return r.ok ? { ok: true as const, reply: r.response } : { ok: false as const, error: r.error }; }
71	    catch (e) { return { ok: false as const, error: (e as Error).message }; }
72	  };
73	  return {
74	    fs: fs as unknown as TxnFs, base: MC, levelName, mcVersion: null,
75	    async baselineErrors() { preLog = await readLog(); return parseBootLog(preLog).errors; },
76	    async restart() {
77	      if (SANDBOX) return { ok: true };
78	      if (!spec) return { ok: false, error: "no control spec for minecraft" };
79	      const before = preLog ?? (await readLog());
80	      try {
81	        const r = await withServerSsh(server, (conn) => sshExec(conn, powerScript(spec, "restart"), 90_000));
82	        const rc = /NXGP:RC:(\d+)/.exec(r.stdout)?.[1];
83	        if (/NXGP:UNIT:NONE/.test(r.stdout)) return { ok: false, error: "the game service was not found" };
84	        if (rc !== "0") return { ok: false, error: `systemctl restart exited ${rc ?? "?"}` };
85	      } catch (e) { return { ok: false, error: (e as Error).message }; }
86	      // wait for a NEW log (Paper rotates latest.log at start) that reaches Done, or gives up (health then says so)
87	      const until = Date.now() + 300_000;
88	      while (Date.now() < until) {
89	        await sleep(5000);
90	        const now = await readLog().catch(() => "");
91	        if (now && now !== before && (parseBootLog(now).cameUp || /Stopping server|FATAL|Registry loading errors/.test(now))) break;
92	      }
93	      preLog = null;
94	      return { ok: true };
95	    },
96	    ...(SANDBOX ? {} : { console: rcon }),
97	    async health(): Promise<HealthReport> {
98	      if (SANDBOX) return { real: false, cameUp: false, answered: false, pluginsEnabled: [], errorLines: [], datapacksLoaded: [], evidence: ["sandbox: no real server"] };
99	      const log = parseBootLog(await readLog());
100	      const list = await rcon("list");
101	      const dps = await rcon("datapack list enabled");
102	      return {
103	        real: true, cameUp: log.cameUp, answered: list.ok, pluginsEnabled: log.enabled, errorLines: log.errors,
104	        datapacksLoaded: dps.ok ? [...dps.reply.matchAll(/file\/([A-Za-z0-9_.-]+?\.zip)/g)].map((m) => `file/${m[1]}`) : [],
105	        evidence: [log.cameUp ? "Done line found" : "no Done line", list.ok ? "answers list" : `list: ${list.ok ? "" : list.error}`],
106	      };
107	    },
108	    close() { (fs as unknown as { close?: () => void }).close?.(); },
109	  };
110	}
