112	/** Nxeon's DeliveryHost for one server. */
113	export function nxeonDeliveryHost(server: ServerRow, ctx: { rootBuildId?: string | null; buildId?: string | null }, env: Record<string, string | undefined> = process.env): DeliveryHost {
114	  const catalog = loadCatalog();
115	  const facts = serverFacts(server, "minecraft");
116	  const mdeps = (fs: TxnFs) => ({ db, catalog, installer: engineManagedInstaller({ env, open: async () => ({ fs: fs as unknown as GuestFs, server: facts }) }) });
117	  const pluginNameOf = (key: string) => catalog.find((e) => e.key === key)?.pluginName ?? key;
118	  const cyrusInstaller = engineInstallerFor("minecraft", "cyrus");
119	  const engineDeps = (fs: TxnFs) => ({ fs: fs as unknown as GuestFs, fetcher: safeFetch, mirror: dbMirrorLookup((sql, ...args) => db.$queryRawUnsafe(sql, ...args)) });
120	  const store = selectPackStore(env);
121	  return {
122	    env,
123	    async open() {
124	      const fs: GuestFs = SANDBOX ? new LocalGuestFs(sandboxGuestRoot(server.id)) : await SshGuestFs.open(server);
125	      const props = (await fs.readFile(`${MC}/server.properties`, 256 * 1024))?.toString("utf8") ?? "";
126	      const level = /^level-name=([A-Za-z0-9_-]{1,64})\s*$/m.exec(props)?.[1] ?? "world";
127	      return session(server, fs, level);
128	    },
129	    managed: {
130	      async ensure(a) { const r = await ensureManagedPlugin(mdeps(a.fs), a); return r.ok ? { ok: true, action: r.action, pluginName: pluginNameOf(a.key) } : { ok: false, error: r.error }; },
131	      async release(a) { const r = await releaseManagedPlugin(mdeps(a.fs), a); return r.ok ? { ok: true, action: r.action } : { ok: false, error: r.error }; },
132	      snapshot: (serverId) => snapshotServerManaged(db, serverId),
133	      async restore(_serverId, snap) { try { await restoreServerManaged(db, snap as ManagedSnapshot); return { ok: true }; } catch (e) { return { ok: false, error: (e as Error).message }; } },
134	    },
135	    jar: {
136	      async install({ fs, base, release, previous }) {
137	        if (!cyrusInstaller || !ctx.rootBuildId) return { ok: false, error: "the Cyrus installer is not available" };
138	        const gm = await ensureCyrusGameMod(ctx.rootBuildId);
139	        if (!gm) return { ok: false, error: "this Cyrus mod has no catalogue row" };
140	        const r = await installOrUpdate(cyrusInstaller, catalogFacts(gm, { targetVersionId: release.modBuildId ?? null }), facts, engineDeps(fs), previous ? "update" : "install");
141	        if (!r.ok) return { ok: false, error: r.error };
142	        return { ok: true, target: `${base}/plugins/${r.fileName ?? release.plugin!.jarName}` };
143	      },
144	      async remove({ fs }) {
145	        if (!cyrusInstaller || !ctx.rootBuildId) return { ok: false, error: "the Cyrus installer is not available" };
146	        const gm = await ensureCyrusGameMod(ctx.rootBuildId);
147	        if (!gm) return { ok: false, error: "this Cyrus mod has no catalogue row" };
148	        const r = await engineUninstall(cyrusInstaller, catalogFacts(gm), facts, engineDeps(fs));
149	        return r.ok ? { ok: true } : { ok: false, error: r.error };
150	      },
151	    },
152	    // Mod Packs: members go through the Mods engine (its state file records them); off unless CYRUS_MODPACK_INSTALL_REAL=1
153	    modpackPlacer: (fs, _session, packId) => engineMemberPlacer({ fs: fs as unknown as GuestFs, server: facts, packId, env }),
154	    ...(store.ok ? { packs: { store: store.store, async publish(zip) { const p = await publishPack(store.store, zip, { maxBytes: store.maxBytes }); if (!p.ok) throw new Error(p.error); return { url: p.url }; } } } : {}),
155	  };
156	}
