158	/** Nxeon's deps for the host-neutral job body (lib/cyrus/delivery/job.ts). */
159	export const nxeonDeliveryJobDeps = (env: Record<string, string | undefined> = process.env): DeliveryJobDeps<ServerRow> => ({
160	  env,
161	  server: (id) => loadServer(id),
162	  build: (id) => cyrusDb.modBuild.findUnique({ where: { id } }),
163	  readJar: (p) => readFile(p).catch(() => null),
164	  projectForRoot: (root) => projectForRootBuild(root),
165	  project: (id) => cyrusDb.cyrusProject.findUnique({ where: { id } }),
166	  // Config Studio (op "config"): the saved settings are re-read from the owner's project in the studio store (never from the payload)
167	  configRelease: configReleaseDep({ store: prismaStudioStore, source: configSourceOf }),
168	  datapackAssets: (revisionId) => cyrusDb.cyrusProjectAsset.findMany({ where: { revisionId, kind: "datapack" }, select: { assetKey: true, provenance: true } }),
169	  host: (server, ctx) => nxeonDeliveryHost(server, ctx, env),
170	  async storeResult(jobId, result) {
171	    const cur = await db.job.findUnique({ where: { id: jobId }, select: { payload: true } });
172	    const prev = (cur?.payload && typeof cur.payload === "object" ? cur.payload : {}) as Record<string, unknown>;
173	    await db.job.update({ where: { id: jobId }, data: { payload: { ...prev, result: { cyrusDelivery: result } } as Prisma.InputJsonValue } });
174	  },
175	  audit: async (userId, action, detail) => { await db.auditLog.create({ data: { userId, action, detail } }); },
176	  async installRow(u) {
177	    if (u.kind === "delivered") await db.serverMod.update({ where: { id: u.serverModId }, data: { status: "INSTALLED", versionId: u.buildId, fileName: u.jarName, error: null, targetVersionId: null } });
178	    else if (u.kind === "removed") await db.serverMod.delete({ where: { id: u.serverModId } });
179	    else if (u.kind === "restore") await db.serverMod.update({ where: { id: u.serverModId }, data: { status: u.prev.status, versionId: u.prev.versionId, error: u.error, targetVersionId: null } });
180	    else await db.serverMod.update({ where: { id: u.serverModId }, data: { status: "FAILED", error: u.error, targetVersionId: null } });
181	  },
182	  noRetry: (jobId) => noRetry(jobId),
183	  // the store is per account (NXEON_MODBUILD_DIR/modpacks/<userId>/...): the job opens only the server owner's packs
184	  async modpack(userId, ref) {
185	    const zip = await modPackStore.readVersion(userId, ref.packId, ref.versionId).catch(() => null);
186	    return zip ? openPackArchive(zip, ref) : { ok: false, error: "the Mod Pack version was not found" };
187	  },
188	});
189	const modPackStore = new FsModPackStore();
