/** Plugins known to own the server's resource pack (they build/send their own; ours would stack or be replaced). */
export const KNOWN_PACK_OWNERS = ["ResourcePackManager", "Oraxen", "Nexo", "ItemsAdder", "ForcePack", "ServerResourcePack"] as const;

export type PackChange =
  | { op: "upsert"; namespace: string; role: string; sha1: string; prompt?: string; required?: boolean; owner?: string }
  | { op: "remove"; namespace: string; role: string };
/** What the server inventory knows (data, read elsewhere): installed plugin names, current server.properties. */
export type PackInventory = { plugins?: string[]; serverProperties?: Record<string, string> };

export type PackChangeResult =
  | { ok: true; config: LoaderConfig; action: "added" | "updated" | "unchanged" | "removed" | "absent"; id: string; changed: boolean; warnings: Issue[] }
  | { ok: false; code: string; error: string };

/**
 * Apply one pack change to the loader config. Existing entries keep their position (pack stacking order is the
 * list order); new ones are appended. The URL is always the immutable `/p/<sha1>.zip` for the sha1.
 */
export function applyPackChange(current: LoaderConfig | null, change: PackChange, ctx: { urlFor: (sha1: string) => string }, inv: PackInventory = {}): PackChangeResult {
  let id: string;
  try { id = packIdFor(change.namespace, change.role); } catch (e) { return { ok: false, code: "bad_identity", error: (e as Error).message }; }
  const base: LoaderConfig = current ? { schema: 1, packs: current.packs.map((p) => ({ ...p })) } : { schema: 1, packs: [] };
  const v = validateLoaderConfig(base);
  if (!v.ok) return { ok: false, code: "current_invalid", error: `the server's current pack config is invalid: ${v.errors.map((e) => e.message).join("; ")}` };
  const warnings = inventoryWarnings(inv);
  const idx = base.packs.findIndex((p) => p.id === id);
  if (change.op === "remove") {
    if (idx < 0) return { ok: true, config: base, action: "absent", id, changed: false, warnings };
    base.packs.splice(idx, 1);
    return { ok: true, config: base, action: "removed", id, changed: true, warnings };
  }
  if (!SHA1_RE.test(change.sha1)) return { ok: false, code: "bad_sha1", error: "sha1 must be 40 lower-case hex chars" };
  if (change.prompt != null && change.prompt.length > MAX_PROMPT) return { ok: false, code: "bad_prompt", error: `prompt longer than ${MAX_PROMPT} chars` };
  const entry: LoaderPack = {
    id, url: ctx.urlFor(change.sha1), sha1: change.sha1,
    ...(change.prompt ? { prompt: change.prompt } : {}),
    required: change.required ?? false,
    owner: change.owner ?? change.namespace, role: change.role,
  };
  if (idx < 0) {
    if (base.packs.length >= MAX_PACKS) return { ok: false, code: "too_many", error: `this server already has ${MAX_PACKS} Nxeon packs` };
    base.packs.push(entry);
  } else {
    const same = serializeLoaderConfig({ schema: 1, packs: [base.packs[idx]] }) === serializeLoaderConfig({ schema: 1, packs: [entry] });
    if (same) return { ok: true, config: base, action: "unchanged", id, changed: false, warnings };
    base.packs[idx] = entry;
  }
  const after = validateLoaderConfig(base);
  if (!after.ok) return { ok: false, code: "result_invalid", error: after.errors.map((e) => e.message).join("; ") };
  return { ok: true, config: base, action: idx < 0 ? "added" : "updated", id, changed: true, warnings };
}

function inventoryWarnings(inv: PackInventory): Issue[] {
  const out: Issue[] = [];
  const names = new Set((inv.plugins ?? []).map((n) => n.toLowerCase()));
  for (const o of KNOWN_PACK_OWNERS) {
    if (names.has(o.toLowerCase())) out.push({ code: "pack_owner_present", message: `${o} also manages a resource pack on this server. Nxeon's packs are sent as extra packs; if ${o} replaces all packs on join, ours can be dropped. Merging into ${o}'s pack is not built yet.` });
  }
  const rp = inv.serverProperties?.["resource-pack"];
  if (rp && rp.trim()) out.push({ code: "server_properties_pack", message: "server.properties already sends a resource pack; Nxeon's packs stack on top of it." });
  return out;
}

