// Dev server for LocalDiskStore pack objects: GET /p/<sha1>.zip. Inert (404) unless the selected pack store is the
// local one (CYRUS_PACK_STORE=local, or unset outside production). In production the public base points at object
// storage on an Nxeon domain and this route is never hit.
import { selectPackStore } from "@/lib/cyrus/packhost/config";
import { LocalDiskStore } from "@/lib/cyrus/packhost/local";
import { IMMUTABLE_CACHE_CONTROL, PACK_CONTENT_TYPE, parsePackFile } from "@/lib/cyrus/packhost/types";

export const dynamic = "force-dynamic";

const notFound = () => new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });

async function serve(file: string, head: boolean) {
  const sha1 = parsePackFile(file);
  if (!sha1) return notFound();
  const sel = selectPackStore();
  if (!sel.ok || !(sel.store instanceof LocalDiskStore)) return notFound();
  const bytes = await sel.store.read(sha1);
  if (!bytes) return notFound();
  return new Response(head ? null : new Uint8Array(bytes), {
    headers: {
      "Content-Type": PACK_CONTENT_TYPE,
      "Content-Length": String(bytes.length),
      "Cache-Control": IMMUTABLE_CACHE_CONTROL,
      ETag: `"${sha1}"`,
      "X-Content-Type-Options": "nosniff",
    },
  });
}

export async function GET(_req: Request, { params }: { params: Promise<{ file: string }> }) {
  return serve((await params).file, false);
}
export async function HEAD(_req: Request, { params }: { params: Promise<{ file: string }> }) {
  return serve((await params).file, true);
}
