// Cyrus R5 delivery: the pure rules (flags, apply semantics, health expectations, record paths). No I/O.
import { DATAPACK_DELIVERY_FLAG } from "../datapack/deliver";
import { worldgenOn } from "../datapack/route";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { CREATURES_FLAG } from "../creature/deliver";
import { MODPACK_REAL_FLAG } from "../modpack/engine-placer";
import type { DeliveryRecord, Env, HealthExpect, HealthReport, HealthVerdict } from "./types";
import { cyrusConfig } from "../config";

/** Master switch for the whole orchestrator (worker). OFF by default: nothing opens a server. */
export const DELIVERY_FLAG = "CYRUS_DELIVERY";
export const DELIVERY_RECORD_DIR = `${cyrusConfig().guest.stateDir}/deliveries`;
export const PACK_LOADER_KEY = "nxeon-pack-loader";
export const PACK_LOADER_PLUGIN = "NxeonPackLoader";
export const BETTERMODEL_KEY = "bettermodel";
export const BETTERMODEL_PLUGIN = "BetterModel";
/** Paths whose writes are never journaled: the Mods engine's and the Mod Pack unit's own rotating backup caches. */
export const JOURNAL_PASSTHROUGH = [cyrusConfig().guest.modsBackupDir, `${cyrusConfig().guest.stateDir}/modpack-backups`];

export type Switches = { delivery: boolean; managed: boolean; datapacks: boolean; worldgen: boolean; creatures: boolean; modpacks: boolean };
export function switches(env: Env): Switches {
  return {
    delivery: env[DELIVERY_FLAG] === "1",
    managed: env[MANAGED_REAL_FLAG] === "1",
    datapacks: env[DATAPACK_DELIVERY_FLAG] === "1",
    worldgen: worldgenOn(env),
    creatures: env[MANAGED_REAL_FLAG] === "1" && env[CREATURES_FLAG] === "1",
    modpacks: env[MODPACK_REAL_FLAG] === "1",
  };
}

export const recordPath = (projectId: string) => {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(projectId)) throw new Error("bad project id");
  return `${DELIVERY_RECORD_DIR}/${projectId}.json`;
};
export const datapackFile = (namespace: string, name: string) => `nxeon-${namespace}-${name}.zip`;
export const datapackId = (file: string) => `file/${file}`;
export const dependentFor = (projectId: string) => `project:${projectId}`;
export const packDependent = (packId: string) => `mod:${packId}`;

export function readRecord(raw: Buffer | null): DeliveryRecord | null {
  if (!raw) return null;
  try {
    const r = JSON.parse(raw.toString("utf8")) as DeliveryRecord;
    return r && r.schema === 1 && typeof r.projectId === "string" && Array.isArray(r.datapacks) && Array.isArray(r.models) ? r : null;
  } catch { return null; }
}

export type ApplyInput = {
  jarChanged: boolean;
  managedChanged: boolean;
  datapacks: { changed: boolean; apply: "reload" | "restart"; worldgen: boolean }[];
  modelsChanged: boolean;
  managedConfigChanged: boolean;
  loaderChanged: boolean;
  /** Config Studio: a values-only config.yml change and how its settings say it takes effect. */
  config?: { changed: boolean; applies: "live" | "reload" | "restart"; reloadCommand?: string };
};
/** `pluginReload`: the mod's own reload command (no slash), run over the console after the files are placed; a failing reply rolls back. */
export type ApplyPlan = { mode: "restart" | "reload" | "none"; reasons: string[]; consoleAfter: string[]; requireCameUp: boolean; handoff: boolean; pluginReload?: string };

/**
 * How the change takes effect (VERIFIED behaviour, docs R0-R4): plugin jars (ours or managed) load only at start ->
 * restart; registry content (enchantments) and world generation load only at start -> restart (worldgen: the server
 * must reach Done, a broken pack stops it); BetterModel models load at start and its pack hand-off must follow that
 * restart; reloadable data packs -> `minecraft:reload`; a Pack Loader config change alone is picked up by the plugin
 * (`nxpacks reload`, or its file watch within ~10 s).
 */
export function planApply(i: ApplyInput): ApplyPlan {
  const reasons: string[] = [];
  if (i.jarChanged) reasons.push("a plugin jar changed (plugins load at server start)");
  if (i.managedChanged) reasons.push("an Nxeon-managed plugin was installed, upgraded or removed");
  const wg = i.datapacks.some((d) => d.changed && d.worldgen);
  if (wg) reasons.push("world generation changed (loads only at server start)");
  if (i.datapacks.some((d) => d.changed && d.apply === "restart" && !d.worldgen)) reasons.push("a data pack adds registry content (loads only at server start)");
  if (i.modelsChanged || i.managedConfigChanged) reasons.push("animated creature models changed (BetterModel loads them at start)");
  const cfg = i.config?.changed ? i.config : null;
  if (cfg && (cfg.applies === "restart" || (cfg.applies === "reload" && !cfg.reloadCommand))) reasons.push(cfg.applies === "restart" ? "a changed setting only loads at server start" : "a changed setting needs a reload, but the mod has no reload command");
  const restart = reasons.length > 0;
  const reload = !restart && i.datapacks.some((d) => d.changed);
  const consoleAfter: string[] = [];
  if (i.loaderChanged) consoleAfter.push("nxpacks reload");
  const pluginReload = !restart && cfg?.applies === "reload" && cfg.reloadCommand ? cfg.reloadCommand.replace(/^\//, "") : undefined;
  return {
    mode: restart ? "restart" : reload ? "reload" : "none",
    reasons: restart ? reasons : reload ? ["data pack content is reloadable (minecraft:reload)"] : pluginReload ? [`the mod re-reads its settings with /${pluginReload}`] : cfg?.applies === "live" ? ["the mod re-reads these settings on its own"] : i.loaderChang
    consoleAfter, requireCameUp: wg || restart, handoff: i.modelsChanged || i.managedConfigChanged, ...(pluginReload ? { pluginReload } : {}),
  };
}

/** Judge a health report against the expectations. A simulated probe is never a pass. */
export function judgeHealth(expect: HealthExpect, r: HealthReport | null, baseline: string[] = []): HealthVerdict {
  const problems: string[] = [];
  if (!r) return { ok: false, problems: ["the health probe did not run"], report: null };
  if (!r.real) problems.push("the health probe was simulated (no real server): not verified");
  if (!r.cameUp) problems.push(expect.worldgen ? "the server did not come up after the restart (world generation stops a server that cannot load it)" : "the server did not come up");
  if (r.cameUp && !r.answered) problems.push("the server came up but does not answer commands");
  const enabled = new Set(r.pluginsEnabled.map((p) => p.toLowerCase()));
  for (const p of expect.plugins) if (!enabled.has(p.toLowerCase())) problems.push(`plugin ${p} is not enabled`);
  for (const p of expect.pluginsGone ?? []) if (enabled.has(p.toLowerCase())) problems.push(`plugin ${p} is still enabled`);
  const norm = (l: string) => l.replace(/^\[[^\]]*\]\s*/, "").replace(/\d{2}:\d{2}:\d{2}/g, "").trim();
  const base = new Set(baseline.map(norm));
  const fresh = r.errorLines.filter((l) => !base.has(norm(l)));
  if (fresh.length) problems.push(`new error lines in the server log: ${fresh.slice(0, 3).join(" | ").slice(0, 400)}`);
  const loaded = new Set(r.datapacksLoaded);
  for (const d of expect.datapacks) if (!loaded.has(d)) problems.push(`data pack ${d} is not loaded`);
  return { ok: problems.length === 0, problems, report: r };
}

/** Dimension world folders a removed worldgen pack leaves (KEPT on uninstall: players' builds live there). */
export function dimensionFolders(base: string, level: string, dims: string[]): string[] {
  return [...new Set(dims)].filter((d) => /^[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(d)).map((d) => { const [ns, path] = d.split(":"); return `${base}/${level}/dimensions/${ns}/${path}`; }).sort();
}

