export type ExecResult = { code: number | null; stdout: string; stderr: string };
/** Runs a shell command line on the build host. `input` is piped to stdin. */
export type Remote = { exec: (command: string, opts?: { input?: Buffer; timeoutMs?: number }) => Promise<ExecResult> };

