/** Paper server jar cached by sha256 and pre-patched (paperclip patch-only) so runs need no network. */
async function ensurePaper(version, build, sha) {
  const dir = path.join(TF_ROOT, "paper", sha);
  const jar = path.join(dir, "paper.jar");
  const meta = path.join(dir, "fill.json");
  const warmed = path.join(dir, ".nxeon-warmed");
  let fill = null;
  if (!fs.existsSync(jar) || sha256File(jar) !== sha) {
    fs.mkdirSync(dir, { recursive: true });
    const api = `https://fill.papermc.io/v3/projects/paper/versions/${encodeURIComponent(version)}/builds/${build}`;
    const r = await fetch(api, { headers: { "User-Agent": "nxeon-testflight/1 (build host)" } });
    if (!r.ok) throw new Error(`Fill API ${api}: HTTP ${r.status}`);
    fill = await r.json();
    const d = fill.downloads && fill.downloads["server:default"];
    if (!d || !d.checksums || d.checksums.sha256 !== sha) throw new Error(`Fill reports sha256 ${d && d.checksums && d.checksums.sha256} for ${version} build ${build}; registry pin is ${sha}`);
    log(`downloading Paper ${version} build ${build} (${fill.channel})`);
    await download(d.url, jar, sha);
    fs.writeFileSync(meta, JSON.stringify({ id: fill.id, channel: fill.channel, time: fill.time, name: d.name, url: d.url, sha256: sha }, null, 1));
  } else if (fs.existsSync(meta)) fill = JSON.parse(fs.readFileSync(meta, "utf8"));
  return { dir, jar, warmed, fill };
