function assertAbs(p: string) {
  if (!isSafeAbs(p)) throw new Error(`unsafe guest path: ${p}`);
}

export class LocalGuestFs implements GuestFs {
  readonly kind = "local" as const;
  constructor(readonly root: string) {}

  private map(p: string): string {
    assertAbs(p);
    const full = path.join(path.resolve(this.root), p);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("path escapes the fake guest root");
    return full;
  }

  /** Resolve the deepest existing ancestor (following links), append the missing tail, map back to a guest path.
   *  Anything that resolves outside the fake root comes back as a path that can never equal a guest path. */
  async realpath(p: string): Promise<string | null> {
    const root = await fsp.realpath(path.resolve(this.root)).catch(() => path.resolve(this.root));
    let cur = this.map(p);
    let tail: string[] = []; // missing segments below `cur`, in order
    for (let hops = 0; hops < 64; hops++) {
      try {
        const r = path.join(await fsp.realpath(cur), ...tail);
        return r === root ? "/" : r.startsWith(root + path.sep) ? r.slice(root.length) : `\u0000outside:${r}`;
      } catch {
        // a dangling link is followed by writes too: resolve its target and keep going
        const l = await fsp.readlink(cur).catch(() => null);
        if (l !== null) { cur = path.resolve(path.dirname(cur), l); continue; }
        const up = path.dirname(cur);
        if (up === cur) return null;
        tail = [path.basename(cur), ...tail]; cur = up;
      }
    }
    return null;
  }
  async stat(p: string): Promise<GuestStat | null> {
    try {
      const s = await fsp.lstat(this.map(p));
      if (s.isSymbolicLink()) return null;
      return { type: s.isDirectory() ? "dir" : "file", size: s.size };
    } catch {
      return null;
    }
  }
  async readFile(p: string, maxBytes = 64 * 1024 * 1024): Promise<Buffer | null> {
    const s = await this.stat(p);
    if (!s || s.type !== "file" || s.size > maxBytes) return null;
    return fsp.readFile(this.map(p));
  }
  async writeFile(p: string, data: Buffer): Promise<void> {
    const f = this.map(p);
    await fsp.mkdir(path.dirname(f), { recursive: true });
    await fsp.writeFile(f, data);
  }
  async mkdirp(p: string): Promise<void> {
    await fsp.mkdir(this.map(p), { recursive: true });
  }
  async rename(from: string, to: string): Promise<void> {
    const t = this.map(to);
    await fsp.mkdir(path.dirname(t), { recursive: true });
    await fsp.rename(this.map(from), t);
  }
  async remove(p: string): Promise<void> {
    await fsp.rm(this.map(p), { recursive: true, force: true });
  }
  async list(dir: string): Promise<string[]> {
    try {
      return await fsp.readdir(this.map(dir));
    } catch {
      return [];
    }
  }
  async chownLike(): Promise<void> {
    /* local fake: nothing to do */
  }
  async copy(from: string, to: string): Promise<void> {
    const t = this.map(to);
    await fsp.mkdir(path.dirname(t), { recursive: true });
    await fsp.copyFile(this.map(from), t);
  }
}

